import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Spinner, Alert, Badge, Button } from 'react-bootstrap';
import { Link, useParams } from 'react-router-dom';
import axios from 'axios';
import ReactMarkdown from 'react-markdown';

const ArticleDetail = () => {
  const { id } = useParams();
  const [article, setArticle] = useState(null);
  const [relatedArticles, setRelatedArticles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchArticle();
  }, [id]);

  const fetchArticle = async () => {
    try {
      setLoading(true);
      setError('');
      
      // Fetch article detail
      const articleResponse = await axios.get(`http://localhost:5000/api/articles/${id}`);
      setArticle(articleResponse.data);

      // Fetch related articles
      const relatedResponse = await axios.get(`http://localhost:5000/api/articles/${id}/related`);
      setRelatedArticles(relatedResponse.data);

    } catch (error) {
      console.error('Error fetching article:', error);
      setError('Gagal memuat artikel. Pastikan backend berjalan di port 5000.');
    } finally {
      setLoading(false);
    }
  };

  const getCategoryLabel = (category) => {
    const labels = {
      nutrition: 'Gizi',
      health: 'Kesehatan',
      lifestyle: 'Gaya Hidup',
      education: 'Pendidikan',
      general: 'Umum'
    };
    return labels[category] || category;
  };

  const getCategoryBadge = (category) => {
    const colors = {
      nutrition: 'success',
      health: 'danger',
      lifestyle: 'warning',
      education: 'info',
      general: 'secondary'
    };
    return colors[category] || 'secondary';
  };

  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString('id-ID', options);
  };

  if (loading) {
    return (
      <Container className="my-5 text-center">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
        <p className="mt-2">Memuat artikel...</p>
      </Container>
    );
  }

  if (error || !article) {
    return (
      <Container className="my-5">
        <Alert variant="danger">
          {error || 'Artikel tidak ditemukan'}
        </Alert>
        <Link to="/articles">
          <Button variant="primary">Kembali ke Artikel</Button>
        </Link>
      </Container>
    );
  }

  return (
    <Container className="my-5">
      {/* Back Button */}
      <Row className="mb-4">
        <Col>
          <Link to="/articles">
            <Button variant="outline-primary">
              ← Kembali ke Artikel
            </Button>
          </Link>
        </Col>
      </Row>

      {/* Article Header */}
      <Row className="justify-content-center">
        <Col lg={10}>
          <Card className="shadow mb-4">
            {article.imageUrl && (
              <Card.Img 
                variant="top" 
                src={article.imageUrl} 
                style={{ maxHeight: '400px', objectFit: 'cover' }}
              />
            )}
            <Card.Body className="p-4">
              {/* Category and Stats */}
              <div className="d-flex justify-content-between align-items-center mb-3">
                <Badge bg={getCategoryBadge(article.category)} size="lg">
                  {getCategoryLabel(article.category)}
                </Badge>
                <div>
                  <small className="text-muted me-3">
                    <i className="bi bi-eye"></i> {article.views} dilihat
                  </small>
                  <small className="text-muted">
                    <i className="bi bi-clock"></i> {article.readTime} menit baca
                  </small>
                </div>
              </div>

              {/* Title */}
              <h1 className="mb-3">{article.title}</h1>

              {/* Author and Date */}
              <div className="d-flex justify-content-between align-items-center mb-4 pb-3 border-bottom">
                <div>
                  <strong>{article.author}</strong>
                </div>
                <div className="text-muted">
                  <i className="bi bi-calendar"></i> {formatDate(article.publishedAt)}
                </div>
              </div>

              {/* Content */}
              <div className="article-content">
                <ReactMarkdown>{article.content}</ReactMarkdown>
              </div>

              {/* Tags */}
              {article.tags && article.tags.length > 0 && (
                <div className="mt-4 pt-3 border-top">
                  <h6>Tags:</h6>
                  <div>
                    {article.tags.map(tag => (
                      <Badge 
                        key={tag} 
                        bg="secondary" 
                        className="me-2"
                        style={{ cursor: 'pointer' }}
                      >
                        #{tag}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Related Articles */}
      {relatedArticles.length > 0 && (
        <Row className="justify-content-center mt-4">
          <Col lg={10}>
            <h4 className="mb-3">📖 Artikel Terkait</h4>
            <Row>
              {relatedArticles.map(related => (
                <Col md={4} key={related._id}>
                  <Card className="h-100 shadow-sm">
                    <Card.Body>
                      <Badge bg={getCategoryBadge(related.category)} className="mb-2">
                        {getCategoryLabel(related.category)}
                      </Badge>
                      <Card.Title className="h6">{related.title}</Card.Title>
                      <Card.Text className="small text-muted">
                        {related.excerpt.substring(0, 60)}...
                      </Card.Text>
                      <Link to={`/articles/${related._id}`}>
                        <Button variant="outline-primary" size="sm">
                          Baca
                        </Button>
                      </Link>
                    </Card.Body>
                  </Card>
                </Col>
              ))}
            </Row>
          </Col>
        </Row>
      )}
    </Container>
  );
};

export default ArticleDetail;