import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Form, Spinner, Alert, Badge, Pagination } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import axios from 'axios';

const Articles = () => {
  const [articles, setArticles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    fetchArticles();
  }, [category, currentPage]);

  const fetchArticles = async () => {
    try {
      setLoading(true);
      setError('');
      
      let url = `http://localhost:5000/api/articles?page=${currentPage}&limit=6`;
      if (category) {
        url += `&category=${category}`;
      }
      if (search) {
        url += `&search=${search}`;
      }

      const response = await axios.get(url);
      setArticles(response.data.articles);
      setTotalPages(response.data.totalPages);
      setTotal(response.data.total);
    } catch (error) {
      console.error('Error fetching articles:', error);
      setError('Gagal memuat artikel. Pastikan backend berjalan di port 5000.');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchArticles();
  };

  const handleCategoryChange = (cat) => {
    setCategory(cat);
    setCurrentPage(1);
  };

  const createSampleArticles = async () => {
    try {
      setLoading(true);
      await axios.post('http://localhost:5000/api/articles/sample');
      await fetchArticles();
    } catch (error) {
      setError('Gagal membuat sample articles');
    }
  };

  const getCategoryLabel = (category) => {
    const labels = {
      nutrition: 'Gizi',
      health: 'Kesehatan',
      lifestyle: 'Gaya Hidup',
      education: 'Pendidikan',
      general: 'Umum'
    };
    return labels[category] || category;
  };

  const getCategoryBadge = (category) => {
    const colors = {
      nutrition: 'success',
      health: 'danger',
      lifestyle: 'warning',
      education: 'info',
      general: 'secondary'
    };
    return colors[category] || 'secondary';
  };

  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString('id-ID', options);
  };

  if (loading && articles.length === 0) {
    return (
      <Container className="my-5 text-center">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
        <p className="mt-2">Memuat artikel...</p>
      </Container>
    );
  }

  return (
    <Container className="my-5">
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h1 className="text-center mb-3">📚 Artikel Edukasi Stunting</h1>
          <p className="text-center lead">
            Baca artikel informatif tentang pencegahan stunting untuk remaja
          </p>
        </Col>
      </Row>

      {/* Search and Filter */}
      <Row className="mb-4">
        <Col md={8} className="mx-auto">
          <Card className="shadow-sm">
            <Card.Body>
              <Form onSubmit={handleSearch}>
                <Row>
                  <Col md={8}>
                    <Form.Group className="mb-3 mb-md-0">
                      <Form.Control
                        type="text"
                        placeholder="Cari artikel..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                      />
                    </Form.Group>
                  </Col>
                  <Col md={4}>
                    <Button type="submit" variant="primary" className="w-100">
                      🔍 Cari
                    </Button>
                  </Col>
                </Row>
              </Form>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Category Filters */}
      <Row className="mb-4">
        <Col>
          <div className="d-flex justify-content-center gap-2 flex-wrap">
            <Button 
              variant={category === '' ? 'primary' : 'outline-primary'}
              onClick={() => handleCategoryChange('')}
              size="sm"
            >
              Semua
            </Button>
            <Button 
              variant={category === 'health' ? 'danger' : 'outline-danger'}
              onClick={() => handleCategoryChange('health')}
              size="sm"
            >
              Kesehatan
            </Button>
            <Button 
              variant={category === 'nutrition' ? 'success' : 'outline-success'}
              onClick={() => handleCategoryChange('nutrition')}
              size="sm"
            >
              Gizi
            </Button>
            <Button 
              variant={category === 'lifestyle' ? 'warning' : 'outline-warning'}
              onClick={() => handleCategoryChange('lifestyle')}
              size="sm"
            >
              Gaya Hidup
            </Button>
            <Button 
              variant={category === 'education' ? 'info' : 'outline-info'}
              onClick={() => handleCategoryChange('education')}
              size="sm"
            >
              Edukasi
            </Button>
          </div>
        </Col>
      </Row>

      {/* Error Alert */}
      {error && (
        <Row className="mb-4">
          <Col>
            <Alert variant="danger">
              {error}
              <div className="mt-2">
                <Button variant="outline-danger" size="sm" onClick={createSampleArticles}>
                  Buat Sample Articles
                </Button>
              </div>
            </Alert>
          </Col>
        </Row>
      )}

      {/* Empty State */}
      {!loading && articles.length === 0 && !error && (
        <Row className="mb-4">
          <Col md={8} className="mx-auto">
            <Card className="text-center py-5">
              <Card.Body>
                <h3>📭 Belum Ada Artikel</h3>
                <p className="text-muted mb-4">Belum ada artikel tersedia saat ini.</p>
                <Button variant="primary" onClick={createSampleArticles}>
                  Buat Sample Articles
                </Button>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {/* Articles Grid */}
      {articles.length > 0 && (
        <>
          <Row className="mb-3">
            <Col>
              <p className="text-muted">
                Menampilkan {articles.length} dari {total} artikel
              </p>
            </Col>
          </Row>

          <Row>
            {articles.map(article => (
              <Col md={6} lg={4} className="mb-4" key={article._id}>
                <Card className="h-100 shadow-sm hover-card">
                  <Card.Img 
                    variant="top" 
                    src={article.imageUrl || 'https://via.placeholder.com/300x200?text=Artikel'} 
                    style={{ height: '200px', objectFit: 'cover' }}
                  />
                  <Card.Body>
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <Badge bg={getCategoryBadge(article.category)}>
                        {getCategoryLabel(article.category)}
                      </Badge>
                      <small className="text-muted">
                        <i className="bi bi-clock"></i> {article.readTime} menit
                      </small>
                    </div>
                    <Card.Title className="h5 mb-2">{article.title}</Card.Title>
                    <Card.Text className="text-muted small mb-2">
                      {article.excerpt.substring(0, 100)}...
                    </Card.Text>
                    <div className="d-flex justify-content-between align-items-center mt-3">
                      <small className="text-muted">
                        <i className="bi bi-person"></i> {article.author}
                      </small>
                      <small className="text-muted">
                        <i className="bi bi-calendar"></i> {formatDate(article.publishedAt)}
                      </small>
                    </div>
                  </Card.Body>
                  <Card.Footer className="bg-white border-0 pb-3">
                    <Link to={`/articles/${article._id}`}>
                      <Button variant="outline-primary" size="sm" className="w-100">
                        Baca Selengkapnya
                      </Button>
                    </Link>
                  </Card.Footer>
                </Card>
              </Col>
            ))}
          </Row>

          {/* Pagination */}
          {totalPages > 1 && (
            <Row className="mt-4">
              <Col>
                <div className="d-flex justify-content-center">
                  <Pagination>
                    <Pagination.First 
                      onClick={() => setCurrentPage(1)} 
                      disabled={currentPage === 1}
                    />
                    <Pagination.Prev 
                      onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                      disabled={currentPage === 1}
                    />
                    
                    {[...Array(totalPages)].map((_, i) => (
                      <Pagination.Item
                        key={i + 1}
                        active={i + 1 === currentPage}
                        onClick={() => setCurrentPage(i + 1)}
                      >
                        {i + 1}
                      </Pagination.Item>
                    ))}
                    
                    <Pagination.Next 
                      onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                      disabled={currentPage === totalPages}
                    />
                    <Pagination.Last 
                      onClick={() => setCurrentPage(totalPages)}
                      disabled={currentPage === totalPages}
                    />
                  </Pagination>
                </div>
              </Col>
            </Row>
          )}
        </>
      )}
    </Container>
  );
};

export default Articles;